import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { WalletModel } from 'src/app/_models';
import { WalletService } from 'src/app/_services';

@Component({
  selector: 'app-wallet-edit',
  host: { 'class': 'childRouteFlex' },
  templateUrl: './wallet-edit.component.html',
  styleUrls: ['./wallet-edit.component.css']
})
export class WalletEditComponent {
	constructor(
        public walletService: WalletService,
        private route: ActivatedRoute,
        private router: Router
    ) {

    }

    private currentWalletId: number | null = null;

    ngOnInit(): void {
        // Access the id parameter from the route snapshot
        this.currentWalletId = parseInt(
            this.route.snapshot.paramMap.get('id') ?? '0'
        );

		if (this.walletService.wallets.length == 0) {
            this.walletService.getWalletsFromServer().subscribe(() => {
                this.walletService.selectWallet(this.currentWalletId ?? 0);
            });
        }
	}

	editWallet() {
		this.walletService.editWallet().subscribe((wallet: WalletModel) => {
			console.log(wallet);
			this.router.navigate(['/wallet', this.currentWalletId]);
		});
	}
}
<div class="component-header">
    <div>
        <i
            class="bi bi-arrow-left-circle pointer"
            [routerLink]="['/wallet', this.walletService.selectedWallet.id]"
            style="cursor: pointer"
        ></i>
        &nbsp;&nbsp;
        <span>{{ this.walletService.selectedWallet.name }}</span>
    </div>
    <span class="header-amount">
        Balance:
        <span class="header-amount-value"
            >{{ this.walletService.selectedWallet.amount }}
            {{ this.walletService.selectedWallet.currencyCode }}</span
        ></span
    >
</div>

<div class="mainChild">
    <div class="default-input composed-input primary">
        <label for="name" class="label">Wallet Name </label>
        <input
            class="no-style-input inner-input"
            type="text"
            id="name"
            [(ngModel)]="this.walletService.selectedWallet.name"
            placeholder="Wallet Name"
        />
    </div>
    <div class="default-input composed-input primary">
        <label for="currencyCode" class="label">Currency Code </label>
        <input
            class="no-style-input inner-input"
            type="text"
            id="currencyCode"
            [(ngModel)]="this.walletService.selectedWallet.currencyCode"
            placeholder="Wallet Currency Code"
        />
    </div>
</div>

<div class="bottom-button">
    <button class="default-button" (click)="editWallet()">
        Confirm Edit Wallet
    </button>
</div>
